/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useCallback, useEffect } from 'react'
import PropTypes from 'prop-types'
import { Button, TreeSelect } from 'antd'
import { get, size } from 'lodash'
import 'codemirror/lib/codemirror.css'
import 'codemirror/theme/material.css'
import 'codemirror/mode/xml/xml'
import { Controlled as CodeMirror } from 'react-codemirror2'
import EditorContainer, { SelectionContainer } from './index.style'
import { handleClickHandler, attributeFormation, childNode, dataAttributeChildPick, atrributesType, creatingLoopingContent } from './attributesFunction'
const { SHOW_ALL } = TreeSelect

export default function Editor ({ html, htmlUpdate, step2Data }) {
  const attributesData = step2Data
  const newAttributeData = attributeFormation(attributesData)
  const [view, toggleView] = useState('Preview')
  const [attribute, selectPdfAttribute] = useState([])
  const [updatedHTML, updateHTMLHandler] = useState('')
  const [intialAttributesData, setInitialAttributes] = useState([])
  const [showSaveButton, setSaveButtonActive] = useState(false)

  useEffect(() => {
    if (newAttributeData.length > 0 && intialAttributesData.length === 0) {
      setInitialAttributes(newAttributeData)
    }
  }, [newAttributeData])

  function handleChange (editor, data, value) {
    htmlUpdate(value)
  }

  function changeValue () {
    if (view === 'html') {
      toggleView('preview')
    } else {
      toggleView('html')
    }
  }

  function updateHTML (html) {
    const updateHTMLData = new XMLSerializer().serializeToString(html)
    updateHTMLHandler(updateHTMLData)
    handleChange('', '', updateHTMLData)
  }

  const onChangeFunction = (e) => {
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(html, 'text/html')
    const getActiveElement = parsedHTML.getElementsByClassName('active-attribute')[0]
    selectPdfAttribute(e)
    const selectedTag = e
    if (getActiveElement) {
      filteringAttributes(getActiveElement, selectedTag)
      updateHTML(parsedHTML)
    }
  }

  const handleInput = useCallback(
    (e) => {
      const htmlValue = e.target.innerHTML
      const parser = new DOMParser()
      const parsedHTML = parser.parseFromString(htmlValue, 'text/html')
      const updateHTMLData = new XMLSerializer().serializeToString(parsedHTML)
      updateHTMLHandler(updateHTMLData)
      handleChange('', '', updateHTMLData)
    }, [updatedHTML]
  )

  const saveHTMLHandler = (saveCheck = '') => {
    if (saveCheck) {
      setSaveButtonActive(false)
      const editableElement = document.querySelectorAll('.contentView')[0]
      if (editableElement.hasAttribute('contenteditable')) {
        editableElement.removeAttribute('contenteditable')
        toggleMode('off')
      }
    } else {
      handleChange('', '', updatedHTML)
    }
    selectPdfAttribute([])
  }

  const onClickHandler = (e) => {
    selectPdfAttribute([])
    const selectedTag = e.target.dataset

    if (updatedHTML) {
      saveHTMLHandler()
    }

    if (size(selectedTag) > 0) {
      if (document.getElementsByClassName('active-attribute').length === 0 || size(selectedTag) > 0) {
        document.getElementsByClassName('product-config-tree-select-id')[0].click()
      }
      const selectedAttribute = get(selectedTag, 'att', '').split('-')[0]
      let filterAttributes = []
      switch (selectedAttribute) {
        case 'normalAttribute':
          filterAttributes = atrributesType(newAttributeData, 'object')
          break
        case 'table':
          filterAttributes = atrributesType(newAttributeData, 'array')
          break
        default: Error('Not a data attribute')
      }
      setInitialAttributes(filterAttributes)
    } else {
      const parser = new DOMParser()
      const parsedHTML = parser.parseFromString(html, 'text/html')
      const activElement = parsedHTML.getElementsByClassName('active-attribute')[0]
      if (activElement) {
        const attributeClass = activElement.getAttribute('class')
        let newClassValue = attributeClass.split(' ')
        newClassValue = newClassValue.filter((item) => item !== 'active-attribute')
        const newValue = newClassValue.join(' ')
        activElement.setAttribute('class', newValue)
        updateHTML(parsedHTML)
      }
    }
    handleClickHandler(e, html, updateHTML)
  }

  const filteringAttributes = (element, selectedTag) => {
    const selectedAttributes = get(element, 'dataset.att', '')
    const type = selectedAttributes.split('-')[0]
    switch (type) {
      case 'normalAttribute':
        element.innerHTML = `{{${selectedTag}}}`
        // let parentNode = document.getElementsByClassName('contentView')
        // parentNode.scrollTop = element.offsetTop'
        document.getElementsByClassName('product-config-tree-select-id')[0].click()
        break
      case 'tableColumn': {
        const columnElement = selectedTag
        const tbody = element.children[0]
        while (tbody.hasChildNodes()) {
          tbody.removeChild(tbody.firstChild)
        }
        const parentRowHead = document.createElement('tr')
        columnElement.forEach(item => {
          const x = parentRowHead.insertCell(-1)
          const items = item.split('.')
          x.innerHTML = items[items.length - 1]
          x.setAttribute('class', 'text-center w10')
        })
        const parentRowData = document.createElement('tr')
        columnElement.forEach(item => {
          const x = parentRowData.insertCell(-1)
          const items = item.split('.')
          x.innerHTML = `{{item.${items[items.length - 1]}}}`
          x.setAttribute('class', 'w20')
        })
        tbody.appendChild(parentRowHead)
        tbody.appendChild(parentRowData)
      }
        break
      case 'table':
        if (selectedTag && selectedTag.length > 0) {
          const selectedElement = selectedTag
          const loopingElementChange = selectedElement.filter(item => !item.includes('['))
          if (loopingElementChange.length > 0) {
            element.innerText = creatingLoopingContent(loopingElementChange[0].split('.'))
          }
          const filterContent = selectedElement.filter(item => item.includes('['))
          const parentElement = element.parentNode
          const childNodesList = parentElement.childNodes
          const selecteElement = dataAttributeChildPick(childNodesList)
          selecteElement.forEach(item => {
            filteringAttributes(item, filterContent)
          })
          document.getElementsByClassName('product-config-tree-select-id')[0].click()
        }

        break
      default: return new Error()
    }
  }

  const toggleMode = (changeType) => {
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(html, 'text/html')
    if (changeType === 'on') {
      const getActiveElementList = parsedHTML.querySelectorAll('.toogle-off')
      getActiveElementList.forEach((item) => {
        const elementsClassValue = item.getAttribute('class')
        const changedData = elementsClassValue.replace('toogle-off', 'toogle-on')
        item.setAttribute('class', changedData)
      })
      updateHTML(parsedHTML)
    } else if (changeType === 'off') {
      let getActiveElementList = parsedHTML.querySelectorAll('.toogle-on')
      getActiveElementList.forEach((item) => {
        const elementsClassValue = item.getAttribute('class')
        const changedData = elementsClassValue.replace('toogle-on', 'toogle-off')
        item.setAttribute('class', changedData)
      })
      getActiveElementList = parsedHTML.querySelectorAll('.active-attribute')
      getActiveElementList.forEach((item) => {
        const elementsClassValue = item.getAttribute('class')
        const changedData = elementsClassValue.replace('active-attribute', 'toogle-off')
        item.setAttribute('class', changedData)
      })
      updateHTML(parsedHTML)
    }
  }

  const editPDFHandler = () => {
    setSaveButtonActive(true)
    const editableElement = document.querySelectorAll('.contentView')[0]
    const editableAttribute = document.createAttribute('contentEditable', true)
    editableElement.setAttributeNode(editableAttribute)
    toggleMode('on')
  }

  return (
    <EditorContainer>

      <div className='editor-container'>
        <div className='editor-title'>
          <Button type='primary' onClick={changeValue}>
            {view === 'html' ? 'Preview' : 'HTML'}
          </Button>
          <SelectionContainer>
            {
              view !== 'html' &&
                <>
                  {
                    showSaveButton
                      ? <Button type='primary' onClick={() => saveHTMLHandler(true)}>Save</Button>
                      : <Button type='primary' onClick={editPDFHandler}>Edit PDF</Button>
                  }
                  <TreeSelect
                    className='product-config-tree-select-id'
                    showSearch
                    allowClear
                    treeCheckable
                    showCheckedStrategy={SHOW_ALL}
                    value={attribute}
                    onChange={onChangeFunction}
                    dropdownStyle={{ maxHeight: 400, overflow: 'auto' }}
                    placeholder='Select Attribute for PDF'
                    treeDefaultExpandAll
                  >
                    {
                      childNode(intialAttributesData)
                    }
                  </TreeSelect>
                </>
            }
          </SelectionContainer>
        </div>
        {
          view === 'html'
            ? <CodeMirror
                onBeforeChange={handleChange}
                value={html}
                className='code-mirror-wrapper'
                options={{
                  lineWrapping: true,
                  lint: true,
                  theme: 'material',
                  mode: 'xml',
                  lineNumbers: true
                }}
              />
            : <div className='contentView' onInput={showSaveButton ? handleInput : null} onClick={showSaveButton ? onClickHandler : null} dangerouslySetInnerHTML={{ __html: html }} />
        }
      </div>
    </EditorContainer>
  )
};

Editor.propTypes = {
  displayName: PropTypes.string.isRequired,
  value: PropTypes.string.isRequired,
  onChange: PropTypes.func.isRequired
}
