import { get, size } from 'lodash'
import { TreeSelect } from 'antd'

export const selectedAttributeItem = []

export function handleClickHandler (e, value, updateHTML) {
  const datanodeValues = e.target.dataset
  if (size(datanodeValues) > 0) {
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(value, 'text/html')
    const previousNode = parsedHTML.querySelectorAll('.active-attribute')[0]

    if (previousNode) {
      const attributeClass = previousNode.getAttribute('class')
      let newClassValue = attributeClass.split(' ')
      newClassValue = newClassValue.filter((item) => item !== 'active-attribute')
      const newValue = newClassValue.join(' ')
      previousNode.setAttribute('class', newValue)
    }
    const changeNode = parsedHTML.querySelectorAll(`[data-att=${e.target.dataset.att}]`)[0]
    if (changeNode.isEqualNode(e.target)) {
      const nodeAttributeValue = changeNode.getAttribute('class')
      const newClassValue = nodeAttributeValue.split(' ')
      newClassValue.push('active-attribute')
      const newValue = newClassValue.join(' ')
      changeNode.setAttribute('class', newValue)
    }

    updateHTML(parsedHTML)
  }
}

export function attributeFormation (data) {
  return data.map(item => {
    if (item.nested.length > 0) {
      item = {
        ...item,
        key: item.name,
        value: '',
        children: attributeFormation(item.nested),
        nested: attributeFormation(item.nested)
      }
      return item
    }
    return {
      ...item,
      key: item.name,
      value: '',
      children: item.nested
    }
  })
}

export function childNode (data, parent = '', isArray = false) {
  if (isArray) {
    return data.map((item, index) => {
      if (item.nested.length === 0) {
        const data = (
          <div>
            <span className='main-text'>{item.name}</span> <br />
            <span className='sub-text'>({item.attribute_type})</span>
          </div>
        )
        return (
          <TreeSelect.TreeNode value={`${parent}[${index}].${item.code}`} title={data} />
        )
      } else {
        return (
          <TreeSelect.TreeNode title={item.name} value={`${parent}.${item.code}`}>
            {childNode(item.nested, `${parent}.${item.code}`, item.is_array)}
          </TreeSelect.TreeNode>
        )
      }
    })
  } else {
    return data.map((item, index) => {
      if (item.nested.length === 0) {
        const data = (
          <div>
            <span className='main-text'>{item.name}</span> <br />
            <span className='sub-text'>({item.attribute_type})</span>
          </div>
        )
        return (
          <TreeSelect.TreeNode value={parent ? `${parent}.${item.code}` : item.code} title={data} />
        )
      } else {
        return (
          <TreeSelect.TreeNode title={item.name} value={parent ? `${parent}.${item.code}` : item.code}>
            {childNode(item.nested, item.code, item.is_array)}
          </TreeSelect.TreeNode>
        )
      }
    })
  }
}

export function dataAttributeChildPick (data) {
  const element = []

  function traverse (data) {
    data.forEach((item, index) => {
      if (item.childNodes.length !== 0) {
        const columnNode = get(item, 'dataset.att', '').split('-')[0]
        if (columnNode === 'tableColumn') {
          element.push(item)
        } else {
          traverse(item.childNodes)
        }
      }
    })
  }
  traverse(data)
  return element
}

export function atrributesType (data, type) {
  // eslint-disable-next-line array-callback-return
  return data.filter(item => {
    if (item.nested.length === 0) {
      if (type === 'object') {
        if (!item.is_array) {
          return item
        }
      } else {
        if (item.is_array) {
          return item
        }
      }
    } else {
      if (type === 'object') {
        if (!item.is_array) {
          return atrributesType(item.nested, type)
        }
      } else {
        if (item.is_array) {
          return atrributesType(item.nested, type)
        }
      }
    }
  })
}

export function creatingLoopingContent (arr) {
  let resultantText = ''
  let lastIndex = ''
  arr.forEach(item => {
    if (resultantText) {
      resultantText += `{% for itr in ${lastIndex}.${item} %}`
      lastIndex = `${lastIndex}.${item}`
    } else {
      resultantText += `{% for item in ${item} %}`
      lastIndex = 'item'
    }
  })
  return resultantText
}
